base.src/add.js:
export function add(a, b) {
  return a + b;
}

base.test/add.test.js:
import test from "node:test";
import assert from "node:assert/strict";
import { add } from "../src/add.js";

test("adds", () => {
  assert.equal(add(1, 2), 3);
});

test("adds negatives", () => {
  assert.equal(add(-1, -2), -3);
});

